"use client";

import { useState } from "react";
import Navbar from "../components/Navbar";
import Hero from "../components/Hero";
import ModeSwitcher from "../components/ModeSwitcher";

export default function Home() {
  const [mode, setMode] = useState("A");
  const [showExperience, setShowExperience] = useState(false);
  const [showGallery, setShowGallery] = useState(false);

  const openExperience = () => setShowExperience(true);
  const closeExperience = () => setShowExperience(false);

  const openGallery = () => setShowGallery(true);
  const closeGallery = () => setShowGallery(false);

  return (
    <div className="relative min-h-screen flex flex-col bg-brand-black text-brand-text">
      <ModeSwitcher mode={mode} setMode={setMode} />

      <Navbar
        showExperience={showExperience}
        openGallery={openGallery}
        openExperience={openExperience}
      />

      <Hero
        mode={mode}
        setMode={setMode}
        openExperience={openExperience}
      />

      {/* Placeholders for other sections */}
      <section id="concepto" className="py-20 bg-brand-black text-center">
        <h2 className="text-3xl font-serif text-white">Concepto (Migrating...)</h2>
      </section>

      <section id="ventajas" className="py-20 bg-brand-dark text-center">
        <h2 className="text-3xl font-serif text-white">Ventajas (Migrating...)</h2>
      </section>

      <footer className="py-10 bg-brand-black text-center border-t border-white/10">
        <p className="text-brand-muted text-xs">© 2026 Freedom Lifestyle Key</p>
      </footer>

      {/* Experience Overlay Placeholder */}
      {showExperience && (
        <div className="fixed inset-0 z-[120] bg-black text-white flex items-center justify-center">
          <div className="text-center">
            <h2 className="text-4xl font-serif mb-4">Experiencia en Construcción</h2>
            <button onClick={closeExperience} className="px-6 py-3 border border-brand-gold text-brand-gold hover:bg-brand-gold hover:text-black transition">
              Cerrar
            </button>
          </div>
        </div>
      )}

      {/* Gallery Placeholder */}
      {showGallery && (
        <div className="fixed inset-0 z-[110] bg-black/90 text-white flex items-center justify-center">
          <div className="text-center">
            <h2 className="text-4xl font-serif mb-4">Galería en Construcción</h2>
            <button onClick={closeGallery} className="px-6 py-3 border border-brand-gold text-brand-gold hover:bg-brand-gold hover:text-black transition">
              Cerrar
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
